--- a/internal/db/query.go
+++ b/internal/db/query.go
@@ -12,7 +12,7 @@ func GetUser(db *sql.DB, username string) (*User, error) {
-	query := fmt.Sprintf("SELECT * FROM users WHERE username='%s'", username)
-	rows, err := db.Query(query)
+	rows, err := db.Query("SELECT * FROM users WHERE username=$1", username)
 	if err != nil {
 		return nil, err
 	}

func TestGetUserSQLInjection(t *testing.T) {
	db, mock, _ := sqlmock.New()
	defer db.Close()
	mock.ExpectQuery("SELECT").WithArgs("' OR 1=1 --").WillReturnRows(sqlmock.NewRows(nil))
	_, _ = GetUser(db, "' OR 1=1 --")
	if err := mock.ExpectationsWereMet(); err != nil {
		t.Errorf("SQL injection not handled: %v", err)
	}
}
